custom_qss:
/* ============================================================
   SOLARIS part 1 — base, master gradient, menubar, menu
   ============================================================ */

* {
    border: none;
    background-color: transparent !important;
    color: #f3e5c8 !important;
}

/* melt rules first */
QAbstractScrollArea, QFrame, QStackedWidget, QScrollArea, QTabWidget, QWidget {
    background: transparent !important;
    border: none;
}

/* ---------- THE MASTER GRADIENT — strengthened golden-hour sweep ---------- */
QMainWindow {
    background-color: qlineargradient(x1:0, y1:0, x2:0.14, y2:1,
        stop:0 #4d3010, stop:0.28 #382108, stop:0.55 #29170a,
        stop:0.8 #1f1207, stop:1 #331d0d) !important;
    border-top: 1px solid rgba(253,230,138,80);
}
QDialog {
    background-color: qlineargradient(x1:0, y1:0, x2:0.14, y2:1,
        stop:0 #4d3010, stop:0.28 #382108, stop:0.55 #29170a,
        stop:0.8 #1f1207, stop:1 #331d0d) !important;
    border-top: 1px solid rgba(253,230,138,80);
}

/* ---------- menubar ---------- */
QMenuBar {
    background: transparent !important;
}
QMenuBar::item {
    padding: 5px 12px;
    border-radius: 5px;
    background: transparent !important;
    color: #a38a63 !important;
}
QMenuBar::item:selected {
    background: rgba(245,158,11,72) !important;
    color: #fde68a !important;
}
QMenuBar::item:disabled {
    color: #574431 !important;
}

/* ---------- popup card ---------- */
QMenu {
    background: #1c1108 !important;
    border: 1px solid rgba(253,230,138,60);
    border-radius: 8px;
    padding: 6px;
}
QMenu::item {
    padding: 6px 26px 6px 16px;
    border-radius: 5px;
    background: transparent !important;
    color: #f3e5c8 !important;
}
QMenu::item:selected {
    background: rgba(245,158,11,112) !important;
    color: #fffbeb !important;
}
QMenu::item:disabled {
    color: #574431 !important;
}
QMenu::separator {
    height: 1px;
    background: rgba(253,230,138,60)S;
    margin: 6px 8px;
}
QMenu::icon {
    padding-left: 6px;
}

/* ============================================================
   SOLARIS part 2 — toolbars, buttons, inputs, checkboxes
   ============================================================ */

/* ---------- toolbar chrome ---------- */
QToolBar {
    background: transparent !important;
    spacing: 3px;
    padding: 4px;
}
QToolBar::separator {
    background: rgba(253,230,138,60)S;
    width: 1px;
    margin: 6px 4px;
}
QToolBar QToolButton {
    background: transparent !important;
    padding: 5px 8px;
    border-radius: 6px;
    color: #a38a63 !important;
}
QToolBar QToolButton:hover {
    background: rgba(245,158,11,72) !important;
    color: #fde68a !important;
}
QToolBar QToolButton:checked, QToolBar QToolButton:pressed {
    background: rgba(245,158,11,143) !important;
    border-bottom: 2px solid #f59e0b;
    color: #fffbeb !important;
}
QToolBar QToolButton:disabled {
    color: #574431 !important;
}

QToolButton {
    background: transparent !important;
    padding: 5px 8px;
    border-radius: 6px;
    color: #a38a63 !important;
}
QToolButton:hover {
    background: rgba(245,158,11,72) !important;
    color: #fde68a !important;
}
QToolButton:checked, QToolButton:pressed {
    background: rgba(245,158,11,143) !important;
    border-bottom: 2px solid #f59e0b;
    color: #fffbeb !important;
}
QToolButton:disabled {
    color: #574431 !important;
}

/* ---------- buttons: glass with specular sheen ---------- */
QPushButton {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
        stop:0 rgba(245,158,11,40), stop:0.12 rgba(255,251,235,26), stop:1 rgba(245,158,11,40)) !important;
    border-radius: 7px;
    padding: 6px 18px;
    color: #f3e5c8 !important;
}
QPushButton:hover {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
        stop:0 rgba(245,158,11,72), stop:0.12 rgba(255,251,235,26), stop:1 rgba(245,158,11,72)) !important;
    color: #fde68a !important;
}
QPushButton:pressed {
    background: rgba(245,158,11,112) !important;
    padding: 7px 17px 5px 19px;
}
QPushButton:checked {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
        stop:0 rgba(255,251,235,26), stop:0.5 rgba(245,158,11,143), stop:1 rgba(245,158,11,143)) !important;
    border-bottom: 2px solid #f59e0b;
    color: #fffbeb !important;
}
QPushButton:default {
    border-bottom: 2px solid #f59e0b;
}
QPushButton:disabled {
    color: #574431 !important;
}
QPushButton::menu-indicator {
    subcontrol-origin: margin;
    width: 14px;
    height: 10px;
    border: none;
}

/* ---------- inputs ---------- */
QLineEdit, QSpinBox, QDoubleSpinBox, QTextEdit, QPlainTextEdit {
    background-color: rgba(28,17,8,200) !important;
    border-bottom: 2px solid rgba(253,230,138,60);
    border-radius: 5px 5px 0 0;
    padding: 5px 8px;
    color: #fffbeb !important;
    selection-background-color: rgba(245,158,11,58);
    selection-color: #fffbeb;
}
QLineEdit:focus, QSpinBox:focus, QDoubleSpinBox:focus, QTextEdit:focus, QPlainTextEdit:focus {
    border-bottom: 2px solid #f59e0b;
    background-color: rgba(40,25,10,220) !important;
}
QLineEdit:disabled, QSpinBox:disabled, QDoubleSpinBox:disabled,
QTextEdit:disabled, QPlainTextEdit:disabled {
    color: #574431 !important;
}
QSpinBox::up-button, QSpinBox::down-button,
QDoubleSpinBox::up-button, QDoubleSpinBox::down-button {
    background: transparent !important;
    border: none;
    width: 16px;
}

QComboBox {
    background-color: rgba(28,17,8,200) !important;
    border-bottom: 2px solid rgba(253,230,138,60);
    border-radius: 5px 5px 0 0;
    padding: 5px 8px;
    color: #fffbeb !important;
}
QComboBox:hover {
    border-bottom: 2px solid rgba(245,158,11,160);
}
QComboBox:focus {
    border-bottom: 2px solid #f59e0b;
}
QComboBox::drop-down {
    border: none;
    background: transparent !important;
    width: 18px;
}
QComboBox QAbstractItemView {
    background: #1c1108 !important;
    border: 1px solid rgba(253,230,138,60);
    border-radius: 7px;
    padding: 5px;
    selection-background-color: rgba(245,158,11,58);
}
QComboBox:disabled {
    color: #574431 !important;
}

/* ---------- checkboxes: amber chips ---------- */
QCheckBox, QRadioButton {
    color: #f3e5c8 !important;
    background: transparent !important;
    padding: 3px;
}
QCheckBox::indicator, QRadioButton::indicator {
    width: 16px;
    height: 16px;
    background: rgba(245,158,11,40) !important;
    border-radius: 5px;
}
QRadioButton::indicator {
    border-radius: 9px;
}
QCheckBox::indicator:hover, QRadioButton::indicator:hover {
    background: rgba(245,158,11,72) !important;
}
QCheckBox::indicator:checked, QRadioButton::indicator:checked {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
        stop:0 #fbbf24, stop:1 #f59e0b) !important;
}
QCheckBox:disabled, QRadioButton:disabled {
    color: #574431 !important;
}

/* ============================================================
   SOLARIS part 3 — tabs, docks, groupboxes, item views, headers
   ============================================================ */

/* ---------- tabs: specular pill ---------- */
QTabBar {
    background: transparent !important;
}
QTabBar::tab {
    background: transparent !important;
    color: #a38a63 !important;
    padding: 7px 18px;
    border-radius: 6px 6px 0 0;
    margin: 0 2px;
}
QTabBar::tab:hover {
    color: #f3e5c8 !important;
    background: rgba(245,158,11,40) !important;
}
QTabBar::tab:selected {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
        stop:0 rgba(255,251,235,100), stop:0.15 rgba(255,251,235,26), stop:1 rgba(245,158,11,40)) !important;
    color: #fffbeb !important;
    border-bottom: 2px solid #f59e0b;
}
QTabBar::tab:disabled {
    color: #574431 !important;
}
QTabBar::close-button {
    background: transparent !important;
    border: none;
    border-radius: 3px;
}
QTabBar::close-button:hover {
    background: rgba(245,158,11,112) !important;
}
QTabWidget::pane {
    border: none;
    border-top: 1px solid rgba(253,230,138,60)S;
    background: transparent !important;
}

/* ---------- docks ---------- */
QDockWidget {
    background: transparent !important;
    border: none;
}
QDockWidget::title {
    background: transparent !important;
    border: none;
    border-bottom: 1px solid rgba(253,230,138,60)S;
    border-left: 3px solid #f59e0b;
    padding: 7px 10px;
    color: #fbbf24 !important;
    font-weight: 600;
}
QDockWidget::title:disabled {
    color: #574431 !important;
}
QDockWidget::close-button, QDockWidget::float-button {
    background: transparent !important;
    border: none;
    padding: 2px;
    border-radius: 4px;
}
QDockWidget::close-button:hover, QDockWidget::float-button:hover {
    background: rgba(245,158,11,72) !important;
}

/* ---------- group boxes ---------- */
QGroupBox {
    background: transparent !important;
    border: none;
    margin-top: 16px;
    padding-top: 6px;
    font-weight: 600;
    color: #f3e5c8 !important;
}
QGroupBox::title {
    subcontrol-origin: margin;
    subcontrol-position: top left;
    padding: 0 7px;
    background: transparent !important;
    color: #fbbf24 !important;
}

/* ---------- item views ---------- */
QAbstractItemView {
    background: rgba(28,17,8,150) !important;
    border: none;
    border-radius: 7px;
    alternate-background-color: rgba(245,158,11,18);
    selection-background-color: rgba(245,158,11,58);
    selection-color: #fffbeb;
    outline: none;
}
QAbstractItemView::item {
    padding: 4px;
}
QAbstractItemView::item:hover {
    background: rgba(245,158,11,72) !important;
}
QAbstractItemView::item:selected {
    background: rgba(245,158,11,58) !important;
    border-left: 3px solid #f59e0b;
    color: #fffbeb !important;
}
QAbstractItemView::item:selected:!active {
    background: rgba(245,158,11,30) !important;
    border-left: 3px solid rgba(245,158,11,140);
}
QTreeView::item, QTreeWidget::item, QTreeWidgetItem,
QTableView::item, QListView::item, QListWidget::item {
    background: transparent !important;
}
QListView::item:selected, QTreeView::item:selected {
    background: rgba(245,158,11,58) !important;
    color: #fffbeb !important;
}

QHeaderView {
    background: transparent !important;
    border: none;
}
QHeaderView::section {
    background: transparent !important;
    border: none;
    border-bottom: 1px solid rgba(253,230,138,60)S;
    padding: 6px 8px;
    color: #a38a63 !important;
    font-weight: 600;
}
QHeaderView::section:hover {
    color: #f3e5c8 !important;
}

/* ============================================================
   SOLARIS part 4 — scrollbars, sliders, progress, status, misc
   ============================================================ */

/* ---------- scrollbars ---------- */
QScrollBar:vertical {
    background: transparent !important;
    width: 12px;
    margin: 2px;
}
QScrollBar::handle:vertical {
    background: rgba(245,158,11,80);
    border-radius: 5px;
    min-height: 30px;
}
QScrollBar::handle:vertical:hover {
    background: rgba(251,191,36,210);
}
QScrollBar::handle:vertical:pressed {
    background: #fbbf24;
}
QScrollBar::add-line:vertical, QScrollBar::sub-line:vertical {
    height: 0;
    background: none;
    border: none;
}
QScrollBar::add-page:vertical, QScrollBar::sub-page:vertical {
    background: transparent !important;
}
QScrollBar:horizontal {
    background: transparent !important;
    height: 12px;
    margin: 2px;
}
QScrollBar::handle:horizontal {
    background: rgba(245,158,11,80);
    border-radius: 5px;
    min-width: 30px;
}
QScrollBar::handle:horizontal:hover {
    background: rgba(251,191,36,210);
}
QScrollBar::handle:horizontal:pressed {
    background: #fbbf24;
}
QScrollBar::add-line:horizontal, QScrollBar::sub-line:horizontal {
    width: 0;
    background: none;
    border: none;
}
QScrollBar::add-page:horizontal, QScrollBar::sub-page:horizontal {
    background: transparent !important;
}
QScrollBar::corner {
    background: transparent !important;
}

/* ---------- sliders: amber heat fill, cream knob ---------- */
QSlider::groove:horizontal {
    background: rgba(253,230,138,46) !important;
    height: 4px;
    border-radius: 2px;
}
QSlider::sub-page:horizontal {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:0,
        stop:0 #92400e, stop:0.55 #f59e0b, stop:1 #fbbf24) !important;
    border-radius: 2px;
}
QSlider::add-page:horizontal {
    background: rgba(253,230,138,46) !important;
    border-radius: 2px;
}
QSlider::handle:horizontal {
    background: #fffbeb !important;
    width: 13px;
    margin: -5px 0;
    border-radius: 7px;
}
QSlider::handle:horizontal:hover {
    background: #fbbf24 !important;
}
QSlider::groove:vertical {
    background: rgba(253,230,138,46) !important;
    width: 4px;
    border-radius: 2px;
}
QSlider::sub-page:vertical {
    background: qlineargradient(x1:0, y1:1, x2:0, y2:0,
        stop:0 #92400e, stop:0.55 #f59e0b, stop:1 #fbbf24) !important;
    border-radius: 2px;
}
QSlider::add-page:vertical {
    background: rgba(253,230,138,46) !important;
    border-radius: 2px;
}
QSlider::handle:vertical {
    background: #fffbeb !important;
    height: 13px;
    margin: 0 -5px;
    border-radius: 7px;
}
QSlider::handle:vertical:hover {
    background: #fbbf24 !important;
}

/* ---------- progress: layered specular shine ---------- */
QProgressBar {
    background: rgba(245,158,11,40) !important;
    border-radius: 6px;
    text-align: center;
    color: #fffbeb !important;
    min-height: 16px;
}
QProgressBar::chunk {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:0,
        stop:0 #92400e, stop:0.5 #f59e0b, stop:0.92 #fbbf24,
        stop:1 rgba(255,251,235,200)) !important;
    border-radius: 6px;
}

/* ---------- statusbar ---------- */
QStatusBar {
    background: transparent !important;
    border: none;
    border-top: 1px solid rgba(253,230,138,60)S;
    color: #a38a63 !important;
}
QStatusBar QLabel {
    color: #a38a63 !important;
}
QStatusBar::item {
    background: transparent !important;
}

/* ---------- tooltip ---------- */
QToolTip {
    background: #1c1108 !important;
    border: 1px solid rgba(245,158,11,170);
    border-radius: 7px;
    padding: 6px 9px;
    color: #f3e5c8 !important;
}

/* ---------- splitters ---------- */
QSplitter {
    background: transparent !important;
    border: none;
}
QSplitter::handle {
    background: transparent !important;
}
QSplitter::handle:hover {
    background: rgba(245,158,11,72) !important;
}

/* ---------- deep-coverage extras ---------- */
QRadioButton::indicator:disabled, QCheckBox::indicator:disabled {
    background: rgba(167,138,99,30) !important;
}
QMenu::item:selected:disabled {
    background: transparent !important;
}
QToolButton::menu-indicator, QToolBar QToolButton::menu-indicator {
    subcontrol-origin: margin;
    subcontrol-position: bottom right;
    width: 12px;
    height: 8px;
}
